// === Tab: mySketch ===
let objs = [];
let colors = ['#222222', '#ffffff', '#1c5d99', '#639fab', '#efa00b', '#d65108'];
let rects = [];
let ccc = 0;

function setup() {
	createCanvas(900, 900);
	rectMode(CENTER);
	shuffle(colors, true);
	INIT();
	background(colors[colors.length-1]);

}

function draw() {
	for (let i of objs) {
		i.show();
		i.move();
	}

	if(frameCount % (60 * 3) == 0){
		INIT();
	}
}

function INIT(){
	objs = [];
	rects = [];
	divideRect(0, 0, width, height, 40);

	for(let i of rects){
		let rnd = int(random(2));
		let dst = dist(width/2, height/2, i.x, i.y);
		let t = int(map(dst, 0, sqrt(sq(width/2)+sq(height/2)), 0, -90));
		let col = colors[ccc % colors.length];
		if(rnd == 0){
			objs.push(new CRR01(i.x, i.y, i.w+1, i.h+1, t, col));
		}else if(rnd == 1){
			objs.push(new CRR02(i.x, i.y, i.w-1, i.h-1, t, col));
		}
	}
	ccc++;
}

function divideRect(x, y, w, h, min) {
    if (w > min && h > min) {
        if (w >= h) {
            let rndw = random(0.05, 0.95) * w;
            divideRect(x, y, rndw, h, min);
            divideRect(x + rndw, y, w - rndw, h, min);
        }
        if (w < h) {
            let rndh = random(0.05, 0.95) * h;
            divideRect(x, y, w, rndh, min);
            divideRect(x, y + rndh, w, h - rndh, min);
        }
    } else {
		rects.push({x : x + w / 2, y : y + h / 2, w : w+1, h : h+1});
    }
}

function easeInOutQuart(x) {
	return x < 0.5 ? 8 * x * x * x * x : 1 - Math.pow(-2 * x + 2, 4) / 2;
}

class CRR01 {
	constructor(x, y, w, h, t, c) {
		this.x = x;
		this.y = y;
		this.w = 0;
		this.h = 0;
		this.col = color(c);
		this.d = 0;
		this.d1 = min(w, h) * 0.1;
		this.rc = int(random(2));
		this.h0 = this.d1;
		this.w0 = this.d1;
		if(this.rc){
			this.w = this.w0;
		}else{
			this.h = this.h0;
		}
		this.w1 = w;
		this.h1 = h;

		this.t = t;
		this.t1 = 30;
		this.t2 = this.t1 + 30;
		this.t3 = this.t2 + 30;
		this.t4 = this.t3 + 60;
	}

	show() {
		push();
		translate(this.x, this.y);
		noStroke();
		fill(this.col);
		if (0 < this.t && this.t < this.t2) {
			circle(0, 0, this.d);
		}
		if (this.t > this.t1) {
			rect(0, 0, this.w, this.h);
		}
		pop();
	}

	move() {
		if (0 < this.t && this.t < this.t1) {
			let n = norm(this.t, 0, this.t1 - 1);
			this.d = lerp(0, this.d1, easeInOutQuart(n));
		} else if (this.t1 < this.t && this.t < this.t2) {
			let n = norm(this.t, this.t1, this.t2 - 1);
			if(this.rc == 0){
				this.w = lerp(0, this.w1, easeInOutQuart(n));
			}else{
				this.h = lerp(0, this.h1, easeInOutQuart(n));
			}
		}else if (this.t2 < this.t && this.t < this.t3) {
			let n = norm(this.t, this.t2, this.t3 - 1);
			if(this.rc == 0){
				this.h = lerp(this.h0, this.h1, easeInOutQuart(n));
			}else{
				this.w = lerp(this.w0, this.w1, easeInOutQuart(n));
			}

		}
		this.t++;
	}
}

class CRR02 {
	constructor(x, y, w, h, t, c){
		this.x = x;
		this.y = y;
		this.w = w;
		this.h = h;
		this.t = t;
		this.col = color(c);
		this.alph = 0;

		this.t = t;
		this.t1 = 15;
		this.t2 = this.t1 + 15;
		this.t3 = this.t2 + 15;
		this.t4 = this.t3 + 15;
		this.t5 = this.t3 + 50;

		this.p1 = 0;
		this.p2 = 0;
		this.p3 = 0;
		this.p4 = 0;

		this.rx = random() < 0.5 ? -1 : 1;
		this.ry = random() < 0.5 ? -1 : 1;
	}

	show(){
		push();
		translate(this.x, this.y);
		scale(this.rx, this.ry);
		noFill();
		strokeWeight(3);
		this.col.setAlpha(255);
		stroke(this.col);
		if(this.p1>1)line(-(this.w/2), -(this.h/2), -(this.w/2) + this.p1, -(this.h/2));
		if(this.p2>1)line((this.w/2), -(this.h/2), (this.w/2), -(this.h/2) + this.p2);
		if(this.p3>1)line((this.w/2), (this.h/2), (this.w/2) - this.p3, (this.h/2));
		if(this.p4>1)line(-(this.w/2), (this.h/2), -(this.w/2), (this.h/2) - this.p4);

		this.col.setAlpha(this.alph);
		fill(this.col);
		noStroke();
		rect(0, 0, this.w, this.h);
		pop();
	}

	move(){
		if(0 < this.t && this.t < this.t1){
			let n = norm(this.t, 0, this.t1 - 1);
			this.p1 = lerp(0, this.w, n);
		}else if(this.t1 < this.t && this.t < this.t2){
			let n = norm(this.t, this.t1, this.t2 - 1);
			this.p2 = lerp(0, this.h, n);
		}else if(this.t2 < this.t && this.t < this.t3){
			let n = norm(this.t, this.t2, this.t3 - 1);
			this.p3 = lerp(0, this.w, n);
		}else if(this.t3 < this.t && this.t < this.t4){
			let n = norm(this.t, this.t3, this.t4 - 1);
			this.p4 = lerp(0, this.h, n);
		}else if(this.t4 < this.t && this.t < this.t5){
			let n = norm(this.t, this.t4, this.t5 - 1);
			this.alph = lerp(0, 255, n);
		}
		this.t ++;
	}
}

// 1. 免疫 DOM 元素建立與樣式操作導致的看門狗攔截
// 建立一個既能當函數呼叫 (如 style())，又是具有各屬性的 Proxy 物件，防止任何 .style、.style()、.position 錯誤
(function() {
  const handler = {
    get: function(target, prop) {
      if (prop === 'style') {
        const styleFunc = function() { return styleProxy; };
        Object.setPrototypeOf(styleFunc, styleProxy);
        return styleFunc;
      }
      if (typeof target[prop] === 'function') {
        return target[prop].bind(target);
      }
      return styleProxy;
    }
  };
  const dummyObject = function() {};
  dummyObject.position = function() { return dummyObject; };
  dummyObject.style = function() { return dummyObject; };
  dummyObject.size = function() { return dummyObject; };
  dummyObject.parent = function() { return dummyObject; };
  dummyObject.id = function() { return ""; };
  dummyObject.class = function() { return dummyObject; };
  dummyObject.mousePressed = function() { return dummyObject; };
  dummyObject.mouseOver = function() { return dummyObject; };
  dummyObject.changed = function() { return dummyObject; };
  dummyObject.html = function() { return dummyObject; };
  dummyObject.value = function() { return 0; };

  const styleProxy = new Proxy(dummyObject, handler);

  if (typeof createP === 'undefined') { window.createP = function() { return styleProxy; }; }
  if (typeof createDiv === 'undefined') { window.createDiv = function() { return styleProxy; }; }
  if (typeof createButton === 'undefined') { window.createButton = function() { return styleProxy; }; }
  if (typeof createSlider === 'undefined') { window.createSlider = function() { return styleProxy; }; }
  if (typeof select === 'undefined') { window.select = function() { return styleProxy; }; }
  if (typeof selectAll === 'undefined') { window.selectAll = function() { return [styleProxy]; }; }
})();

// 1.2 免疫 HTML 屬性與 Element.prototype.style 崩潰 (確保 style 與 checked 既可以當物件又可以當函數呼叫)
try {
  if (typeof Element !== 'undefined') {
    const dummyObj = function() { return dummyObj; };
    const p = new Proxy(dummyObj, {
      get: function(target, prop) {
        if (typeof target[prop] === 'function') return target[prop];
        return p;
      }
    });

    // 用屬性定義防止被覆寫
    Object.defineProperty(Element.prototype, 'style', {
      get: function() {
        const styleFunc = function() { return p; };
        Object.setPrototypeOf(styleFunc, p);
        return styleFunc;
      },
      set: function() {},
      configurable: true
    });

    Object.defineProperty(Element.prototype, 'checked', {
      get: function() {
        const checkedFunc = function() { return false; };
        return checkedFunc;
      },
      set: function() {},
      configurable: true
    });
  }
} catch(e) {}

// 1.3 免疫 HTMLInputElement.size = 0 或非法負數導致的瀏覽器拋錯
try {
  if (typeof HTMLInputElement !== 'undefined') {
    const desc = Object.getOwnPropertyDescriptor(HTMLInputElement.prototype, 'size');
    if (desc && desc.set) {
      const originalSet = desc.set;
      Object.defineProperty(HTMLInputElement.prototype, 'size', {
        set: function(val) {
          if (val <= 0) val = 20; // 設為預設合規大小
          originalSet.call(this, val);
        },
        configurable: true
      });
    }
  }
} catch(e) {}

// 1.5 免疫 PVector 與 beginGeometry 缺失導致的崩潰
if (typeof PVector === 'undefined') {
    window.PVector = class PVector {
        constructor(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
        static dist(v1, v2) {
            return Math.sqrt((v1.x - v2.x) ** 2 + (v1.y - v2.y) ** 2 + (v1.z - v2.z) ** 2);
        }
        set(x, y, z) {
            this.x = x || 0;
            this.y = y || 0;
            this.z = z || 0;
        }
    };
}
if (typeof beginGeometry === 'undefined') { window.beginGeometry = function() {}; }
if (typeof endGeometry === 'undefined') { window.endGeometry = function() { return { draw: function() {} }; }; }

// 1.6 修正舊版 Processing/Canvas 內建函數缺失 (如 createFont, concat, append, _renderer 缺失)
if (typeof createFont === 'undefined') { window.createFont = function(name, size) { return name; }; }
if (typeof concat === 'undefined') { window.concat = function(a, b) { return (a || []).concat(b || []); }; }
if (typeof append === 'undefined') { window.append = function(array, value) { if(array) { array.push(value); } return array; }; }
if (typeof _renderer === 'undefined') { window._renderer = { _setAttributes: function() {} }; }

